<script setup lang="ts">import{onMounted,ref}from'vue';import{ArrowLeftRight}from'@lucide/vue';import{api,errorMessage}from'../lib/api';import StatusBadge from'../components/StatusBadge.vue';const rows=ref<any[]>([]),recommendations=ref<any[]>([]),loading=ref(true),error=ref('');const next:Record<string,string>={REQUESTED:'APPROVED',APPROVED:'PREPARING',PREPARING:'IN_TRANSIT',IN_TRANSIT:'RECEIVED'};const label=(s:string)=>(next[s]??'').replaceAll('_',' ');async function load(){try{const[a,b]=await Promise.all([api.get('/transfers'),api.get('/inventory/recommendations')]);rows.value=a.data.data;recommendations.value=b.data.data}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}async function confirm(r:any){try{await api.post('/transfers',{sourceLocationId:r.fromLocationId,destinationLocationId:r.toLocationId,items:[{productId:r.productId,quantity:r.quantity}]});await load()}catch(e){error.value=errorMessage(e)}}async function advance(row:any){const status=next[row.status];if(!status)return;try{await api.post(`/transfers/${row.id}/status`,{status});await load()}catch(e){error.value=errorMessage(e)}}onMounted(load)</script>
<template><div class="page-heading"><div><p class="eyebrow">INTERNAL REBALANCING</p><h1>Transfers</h1><p>Turn stock-health recommendations into controlled inventory moves.</p></div></div><div v-if="error" class="form-error">{{error}}</div><h3>Recommended transfers</h3><div class="offer-grid"><article v-for="r in recommendations" :key="`${r.productId}${r.toLocationId}`" class="offer-card"><span class="category">AUTOMATED RECOMMENDATION</span><h3>{{r.productName}}</h3><p>{{r.fromLocation}} → {{r.toLocation}}</p><div class="price"><span>Recommended quantity</span><strong>{{r.quantity}}</strong></div><p class="muted">{{r.reason}}</p><button class="primary wide" @click="confirm(r)">Confirm transfer</button></article></div><article class="panel table-panel" style="margin-top:24px"><div class="table-wrap"><table><thead><tr><th>Route</th><th>Items</th><th>Quantity</th><th>Status</th><th>Next step</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><strong>{{row.sourceLocation.name}} → {{row.destinationLocation.name}}</strong></td><td>{{row.items.map((x:any)=>x.product.name).join(', ')}}</td><td>{{row.items.reduce((s:number,x:any)=>s+x.quantity,0)}}</td><td><StatusBadge :status="row.status"/></td><td><button v-if="next[row.status]" class="text-button success" @click="advance(row)">Move to {{label(row.status)}}</button></td></tr></tbody></table></div><div v-if="!loading&&!rows.length" class="empty"><ArrowLeftRight/><strong>No transfers yet</strong></div></article></template>
